// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 mintAmount, address target) public {
        vm.assume(target != address(0) && target != address(this));
        uint256 oldBalance = c.balanceOf(target);
        c.mintToken(target, mintAmount);
        uint256 newBalance = c.balanceOf(target);
        assertTrue(newBalance == oldBalance + mintAmount);
    }
}
